class Solution {
public:
    int numberOfWays(string corridor) {
        const int MOD = 1e9 + 7;
        long long ans = 1;
        int seatCount = 0;
        int lastSeat = -1;
        for (int i = 0; i < (int)corridor.size(); i++) {
            if (corridor[i] == 'S') {
                seatCount++;
                if (seatCount >= 3 && seatCount % 2 == 1) {
                    ans = (ans * (i - lastSeat)) % MOD;
                }
                lastSeat = i;
            }
        }
        if (seatCount == 0 || seatCount % 2 == 1) return 0;
        return (int)ans;
    }
};
